// Capa de Controlador que procesa las reglas del flujo y conecta el Modelo con la Vista
public class ControladorPrincipal {
    private CatalogoIntegraciones catalogo;
    private ConsolaView vista;

    public ControladorPrincipal() {
        this.catalogo = new CatalogoIntegraciones();
        this.vista = new ConsolaView();
    }

    // Bucle principal de ejecución del sistema, ajustado hasta la opción 5 (Salir)
    public void iniciarAplicacion() {
        int opcion = 0;
        do {
            opcion = vista.mostrarMenuPrincipal();
            procesarOpcionMenu(opcion);
        } while (opcion != 5);
    }

    // Estructura de control basada en la selección del usuario
    public void procesarOpcionMenu(int opcion) {
        switch (opcion) {
            case 1:
                vista.mostrarListaIntegraciones(catalogo.getListaIntegraciones());
                break;
            case 2:
                catalogo.ordenarPorLatencia(); // Ordena usando Collections.sort y compareTo
                vista.mostrarMensaje("\n¡Integraciones ordenadas exitosamente por latencia!");
                vista.mostrarListaIntegraciones(catalogo.getListaIntegraciones());
                break;
            case 3:
                String id = vista.pedirInput("Ingrese el ID de la integración a buscar: ");
                AbstractIntegracion encontrada = catalogo.buscarPorIdentificador(id);
                if (encontrada != null) {
                    vista.mostrarMensaje("\nEncontrada: " + encontrada.mostrarDetalles());
                } else {
                    vista.mostrarMensaje("\nNo se encontró ninguna integración con el ID: " + id);
                }
                break;
            case 4: 
                AbstractIntegracion nueva = vista.solicitarNuevaIntegracion();
                catalogo.agregarIntegracion(nueva);
                vista.mostrarMensaje("\n¡Integración registrada y añadida al catálogo exitosamente!");
                break;
            case 5: 
                vista.mostrarMensaje("Saliendo del sistema...");
                break;
            default:
                vista.mostrarMensaje("Opción inválida.");
        }
    }
}
